import type { ReactElement } from "react";
import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  name: string;
  time: string;
  state: TimeState;
}

export interface TimeListProps {
  items: readonly TimeItem[];
  /** Called when a row is activated with the mouse or keyboard. */
  onSelect?: (item: TimeItem, index: number) => void;
  /** Accessible name for the list. */
  label?: string;
}

const STATE_TEXT: Record<TimeState, string> = {
  past: "passed",
  next: "next",
  later: "later",
};

export function TimeList({
  items,
  onSelect,
  label = "Times of day",
}: TimeListProps): ReactElement {
  return (
    <ul className="time-list" aria-label={label}>
      {items.map((item, index) => {
        const isNext = item.state === "next";

        return (
          <li
            key={`${item.name}-${item.time}-${index}`}
            className={`time-list__item time-list__item--${item.state}`}
          >
            <button
              type="button"
              className="time-list__button"
              aria-current={isNext ? "time" : undefined}
              onClick={() => onSelect?.(item, index)}
            >
              <span className="time-list__name">
                <span className="time-list__dot" aria-hidden="true" />
                <span>{item.name}</span>
                <span className="sr-only">, {STATE_TEXT[item.state]}</span>
              </span>
              <time className="time-list__time">{item.time}</time>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
