.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.time-list {
  list-style: none;
  margin: 0;
  padding: 0;
  font: inherit;
  color: var(--ink);
  border-top: 1px solid var(--hair);
}

.time-list__item {
  border-bottom: 1px solid var(--hair);
}

.time-list__button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  margin: 0;
  padding: clamp(0.6rem, 1.5vw, 0.9rem) clamp(0.75rem, 2vw, 1.25rem);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: clamp(1rem, 2.2vw, 1.4rem);
  text-align: left;
  cursor: pointer;
  transition: background-color 200ms ease, color 200ms ease;
}

.time-list__button:hover {
  background: var(--code-bg);
}

.time-list__button:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}

.time-list__name {
  display: inline-flex;
  align-items: center;
  gap: 0.75em;
  min-width: 0;
}

.time-list__time {
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.time-list__dot {
  flex-shrink: 0;
  width: 0.6em;
  height: 0.6em;
  border-radius: 999px;
  border: 2px solid var(--muted);
  background: transparent;
}

/* Past: quiet text, a filled done dot. */
.time-list__item--past .time-list__button {
  color: var(--muted);
}

.time-list__item--past .time-list__dot {
  border-color: var(--myelin);
  background: var(--myelin);
}

/* Later: default text, hollow dot. */
.time-list__item--later .time-list__button {
  color: var(--ink);
}

/* Next: the highlighted row, in the "what is next" accent. */
.time-list__item--next .time-list__button {
  color: var(--ink);
  font-weight: 600;
  background: var(--cresyl-wash);
  box-shadow: inset 3px 0 0 var(--cresyl);
}

.time-list__item--next .time-list__dot {
  border-color: var(--cresyl);
  background: var(--cresyl);
}

:root[data-motion="reduce"] .time-list__button {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .time-list__button {
    transition: none;
  }
}
